
/* ================= PROJECTS v5 ================= */
const PV={sel:new Set(),group:'status'};
const PNAV=()=>[['projects/home','Home','home'],['projects/mywork','My Work','mywork',allTasks().filter(t=>t.as==='TR'&&t.st!=='done').length,null,'My Work'],['projects/workload','Workload','users'],['projects/portfolio','Portfolio','dash'],['projects/templates','Templates','copy'],['projects/trash','Trash','trash']];
function pShell(cur,body,crumbs,o={}){const live=projs().filter(p=>!p.arch);const grp=[['Client projects',live.filter(p=>p.cl!=='Internal')],[oname()+' projects',live.filter(p=>p.cl==='Internal')]];
const side=`<div class="side-sec sx">Favourites</div><div class="side-list">${live.filter(p=>p.fav).map(p=>pLink(p)).join('')}</div>${grp.map(([g,L])=>`<details class="coll" open><summary class="side-sec sx">${ic('down',14)}${g}<span class="count">${L.length}</span></summary><div class="side-list">${L.map(p=>pLink(p)).join('')}</div></details>`).join('')}<button class="addrow" data-act="newproj">${ic('plus',16)}New project</button><p class="hint" style="padding:6px 12px 0;font-size:12.5px">Archived projects appear only in search.</p>`;
return shell('projects',{nav:PNAV(),cur,body,crumbs:crumbs||[['Projects']],sideMid:side,barRight:`<span class="timerpill" title="Timer running on “Quiz questions v2”">${ic('timer',16)}<b class="mono">0:42:10</b></span><button class="btn primary sm" data-act="quickadd" title="Quick add (Q)">${ic('plus',16,'',2.2)}<span class="hide-m">Task</span></button>`,...o})}
const pLink=p=>`<a href="#/projects/p/${p.id}/list" ${RT.p[1]===p.id?'aria-current="page"':''} data-ctx="proj:${p.id}"><span class="pdot" style="--c:${p.c}"></span><span>${p.n}</span></a>`;
const assignees=t=>`<span class="av-stack">${[t.as,...(t.co||[])].map(k=>av(k)).join('')}</span>`;
const taskRow=t=>`<div class="trow" data-row="${esc(t.n)}" data-ctx="task:${t.id}" aria-selected="${PV.sel.has(t.id)}"><button class="sq" role="checkbox" aria-checked="${PV.sel.has(t.id)}" aria-label="Select ${esc(t.n)}" data-act="psel:${t.id}"><i>${ic('check',12,'',3)}</i></button><button class="cbx" role="checkbox" aria-checked="${t.st==='done'}" aria-label="Mark ${esc(t.n)} done" data-act="tdone:${t.id}"><i style="${t.st==='done'?'background:var(--action);border-color:var(--action)':''}">${t.st==='done'?ic('check',14,'',3).replace('class="ic ','style="opacity:1;transform:none;color:var(--action-ink)" class="ic '):''}</i></button><button class="tname" data-act="task:${t.id}"><span>${t.n}</span>${t.tags.map(g=>`<span class="tag sm">${g}</span>`).join('')}${t.stt?`<span class="sub">${ic('check',12,'',2.4)}${t.sd}/${t.stt}</span>`:''}</button><span class="hm">${assignees(t)}</span><span class="due-c ${t.o<3&&t.st!=='done'?'od':t.o<=4?'soon':''}">${dl(t.o)}</span><span class="hm">${priL(t.pri)}</span></div>`;
VIEWS.projects=p=>{const pg=p[0]||'home';
if(pg==='p')return projectView(p[1],p[2]||'list');
if(pg==='home'){const my=allTasks().filter(t=>t.as==='TR'&&t.st!=='done').sort((a,b)=>a.o-b.o);const live=projs().filter(x=>!x.arch);
return pShell('projects/home',`<div class="p-home"><div><p class="over">Thursday 12 November</p><h1 class="h1">Good ${tod()==='morning'?'morning':tod()==='afternoon'?'afternoon':'evening'}, Tabish</h1></div><div class="kpis">${[[my.filter(t=>t.o<=3).length,'Due today'],[allTasks().filter(t=>t.o<3&&t.st!=='done').length,'Overdue'],[my.filter(t=>t.o<=9).length,'This week'],[live.length,'Active projects'],[live.filter(x=>x.st==='At risk').length,'At risk']].map(([b,s],i)=>`<div class="${i===1&&b?'bad':''}"><b>${b}</b><span>${s}</span></div>`).join('')}</div></div>
<div class="split"><section class="panel"><div class="sec-h"><h2>My priorities</h2><a class="linkbtn" href="#/projects/mywork">My Work</a></div><div class="tasklist">${my.slice(0,7).map(taskRow).join('')}</div></section>
<div class="stackcol"><section class="panel"><div class="sec-h"><h2>Recent projects</h2></div><div class="rows">${live.map(x=>`<a class="linkrow" href="#/projects/p/${x.id}/overview"><span class="pdot" style="--c:${x.c}"></span><span class="main"><b>${x.n}</b><small>${x.cl} · due ${x.due}</small></span><span class="ring xs" style="--v:${x.pr}" title="${x.pr}%"></span></a>`).join('')}</div></section>
<section class="panel"><div class="sec-h"><h2>Templates</h2><a class="linkbtn" href="#/projects/templates">All</a></div><div class="rows">${['Client funnel build','Course launch','Website refresh'].map(n=>`<button class="linkrow" data-act="newproj">${ic('copy')}<span class="main"><b>${n}</b></span></button>`).join('')}</div></section></div></div>`)}
if(pg==='mywork'){const my=allTasks().filter(t=>t.as==='TR'||(t.co||[]).includes('TR'));const G=[['Overdue',t=>t.o<3&&t.st!=='done'],['Today',t=>t.o===3&&t.st!=='done'],['This week',t=>t.o>3&&t.o<=9&&t.st!=='done'],['Later',t=>t.o>9&&t.st!=='done'],['Done',t=>t.st==='done']];
return pShell('projects/mywork',`${head('My Work','Everything assigned to you across projects. Tasks app items show under Office › My day.',vsw([['list','List','list'],['board','Board','board']],'list','noop'))}${G.map(([l,f])=>{const r=my.filter(f);return r.length?`<section class="panel" style="margin-bottom:14px"><div class="sec-h"><h2>${l}</h2><span class="n">${r.length}</span></div><div class="tasklist">${r.map(taskRow).join('')}</div></section>`:''}).join('')}`,[['Projects'],['My Work']])}
if(pg==='workload'){const W=['16 Nov','23 Nov','30 Nov','7 Dec'];return pShell('projects/workload',`${head('Workload','Open tasks and estimated hours per person per week, against a 40-hour week.',`<select class="sel"><option>All projects</option>${projs().filter(x=>!x.arch).map(x=>`<option>${x.n}</option>`).join('')}</select>`)}<div class="tblwrap"><table class="tbl wl"><thead><tr><th>Person</th>${W.map(w=>`<th>Week of ${w}</th>`).join('')}<th>Overdue</th><th>No date</th></tr></thead><tbody>${Object.keys(PEOPLE).map((k,i)=>`<tr><td class="t1"><span style="display:flex;gap:8px;align-items:center">${av(k)}${PEOPLE[k][0]}</span></td>${W.map((w,j)=>{const h=[[22,30,18,8],[44,32,20,12],[18,38,26,10],[34,28,16,6],[12,14,20,22],[8,10,6,4]][i][j];return `<td data-l="${w}"><span class="wcell ${h>40?'over':h>32?'high':''}" style="--v:${Math.min(100,h/40*100)}%"><b>${h}h</b><small>${Math.round(h/4)} tasks</small></span></td>`}).join('')}<td data-l="Overdue">${i===1?'<span class="pill danger">2</span>':'0'}</td><td data-l="No date">${i%3}</td></tr>`).join('')}</tbody></table></div><p class="hint" style="margin-top:10px">“Over 40 h” is flagged in red. Drag a task to another person or week to rebalance (needs the backend).</p>`,[['Projects'],['Workload']])}
if(pg==='portfolio')return pShell('projects/portfolio',`${head('Portfolio','Every project you can open, at a glance.',`<button class="btn ghost" data-act="toast:Exports a PDF or CSV of this view.">${ic('download',18)}Export</button>`)}<div class="toolbar">${vsw([['all','All'],['client','Client'],['internal','Internal']],'all','noop')}<span class="grow"></span><select class="sel"><option>Sort by due date</option><option>Sort by progress</option><option>Sort by risk</option></select></div><div class="tblwrap"><table class="tbl"><thead><tr><th>Project</th><th>Status</th><th>Lead</th><th style="width:170px">Progress</th><th>Open</th><th>Overdue</th><th>Next due</th></tr></thead><tbody>${projs().filter(x=>!x.arch).map(x=>{const T=tasksOf(x.id);return `<tr data-row="${x.n}"><td class="t1"><a class="fname" href="#/projects/p/${x.id}/overview"><span class="pdot" style="--c:${x.c}"></span><span>${x.n}<small>${x.cl}</small></span></a></td><td data-l="Status"><span class="pill ${PSTAT[x.st]}">${x.st}</span></td><td data-l="Lead">${av(x.lead)}</td><td data-l="Progress"><span style="display:flex;gap:8px;align-items:center"><span class="prog" style="flex:1;--v:${x.pr}%"><i></i></span><span class="mono" style="font-size:12.5px">${x.pr}%</span></span></td><td data-l="Open">${T.filter(t=>t.st!=='done').length}</td><td data-l="Overdue">${T.filter(t=>t.o<3&&t.st!=='done').length}</td><td data-l="Next due">${x.due}</td></tr>`}).join('')}</tbody></table></div>`,[['Projects'],['Portfolio']]);
if(pg==='templates')return pShell('projects/templates',`${head('Templates','Start a project with sections, tasks, rules and docs already in place.',`<button class="btn ghost" data-act="toast:Open a project and choose “Save as template”.">${ic('copy',18)}Save a project as template</button>`)}<div class="cardgrid">${[['Client funnel build','5 sections · 32 tasks · 3 rules','#EF5235'],['Course launch','4 sections · 24 tasks','#6B4FF0'],['Website refresh','3 sections · 18 tasks','#2B5CF0'],['Monthly retainer','Recurring tasks','#13A592']].map(([n,s,c])=>`<button class="card" data-act="newproj"><span class="pbig" style="--c:${c};width:44px;height:44px;border-radius:14px">${ic('projects',20,'',2)}</span><h3>${n}</h3><p>${s}</p></button>`).join('')}</div>`,[['Projects'],['Templates']]);
if(pg==='trash')return pShell('projects/trash',`${head('Trash','Archived projects and tasks you moved to trash. Restore within 30 days.')}<div class="tblwrap"><table class="tbl"><thead><tr><th>Item</th><th>Where</th><th>Removed</th><th></th></tr></thead><tbody>${[['Old kickoff checklist','Task · Harry Kaye quiz funnel','2 days ago'],['Q3 ads test','Project (archived)','Sep']].map(([n,w,d])=>`<tr><td class="t1">${n}</td><td data-l="Where">${w}</td><td data-l="Removed">${d}</td><td data-l=""><button class="btn ghost sm" data-act="toast:Restored.:ok">${ic('restore',16)}Restore</button></td></tr>`).join('')}</tbody></table></div>`,[['Projects'],['Trash']]);
return pShell('projects/home','')};
function projectView(id,view){const x=proj(id);if(!x)return pShell('',emptyS(`<span style="font:800 64px/1 var(--font-d);color:var(--line2)">?</span>`,'We couldn’t find that','It may have moved, or you may not have access.',`<a class="btn ink" href="#/projects/home">Go to Projects Home</a>`));
const T=tasksOf(id);const V=[['overview','Overview'],['list','List',T.length],['board','Board'],['calendar','Calendar'],['timeline','Timeline'],['workload','Workload'],['report','Report'],['files','Files & docs'],['rules','Rules']];let body='';
if(view==='overview'){const done=T.filter(t=>t.st==='done').length,od=T.filter(t=>t.o<3&&t.st!=='done').length;body=`<div class="split"><div class="stackcol"><section class="panel" style="padding:20px"><p class="over">Purpose</p><p style="font-size:17px;margin-top:8px">${x.purpose}</p><div class="kpis" style="margin-top:16px">${[[T.length-done,'Open'],[done,'Done'],[od,'Overdue'],['14h','Logged'],['31h','Estimated left']].map(([b,s])=>`<div><b>${b}</b><span>${s}</span></div>`).join('')}</div></section>
<section class="panel"><div class="sec-h"><h2>Status update</h2><button class="linkbtn" data-act="toast:Write a status update for the team.">Write update</button></div><div style="padding:0 20px 18px"><div style="display:flex;gap:10px;align-items:center">${av(x.lead)}<b>${PEOPLE[x.lead][0]}</b><span class="pill ${PSTAT[x.st]}">${x.st}</span><small class="muted">Monday</small></div><p class="tx2" style="margin-top:8px">Copy is moving, design is one day behind. Next: quiz questions v2 to Harry by Friday.</p></div></section>
<section class="panel"><div class="sec-h"><h2>Upcoming deadlines</h2></div><div class="tasklist">${T.filter(t=>t.st!=='done').sort((a,b)=>a.o-b.o).slice(0,4).map(taskRow).join('')}</div></section></div>
<div class="stackcol"><section class="panel" style="padding:18px 20px"><dl class="kv2"><dt>Client</dt><dd>${x.cl==='Internal'?'Internal':`<a href="#/clients/c/hk/overview">${x.cl}</a>`}</dd><dt>Lead</dt><dd style="display:flex;gap:8px;align-items:center">${av(x.lead)}${PEOPLE[x.lead][0]}</dd><dt>Dates</dt><dd>1 Oct → ${x.due}</dd><dt>From plan</dt><dd><a href="#/planner/plan/p1/builder">2027 Growth plan › Acquire</a></dd><dt>Client sees</dt><dd>Milestones only</dd></dl></section>
<section class="panel"><div class="sec-h"><h2>Members</h2><span class="n">${x.team.length}</span><button class="linkbtn" data-act="members:${id}">Manage</button></div><div class="rows">${x.team.map(k=>`<div class="row" style="min-height:50px">${av(k)}<div class="main"><b>${PEOPLE[k][0]}</b><small>${k===x.lead?'Project lead':'Member'}</small></div></div>`).join('')}</div></section></div></div>`}
if(view==='list'){const sel=PV.sel.size;body=`<div class="toolbar"><label class="inp grow">${ic('search',16)}<input placeholder="Find a task" data-filter></label><button class="chip" data-act="noop">${ic('user',14)}Person</button><button class="chip" data-act="noop">${ic('tag',14)}Tag</button><select class="sel" aria-label="Group by" data-pg><option value="status">Group: Status</option><option value="section" ${PV.group==='section'?'selected':''}>Group: Section</option><option>Group: Person</option><option>Group: Priority</option></select><button class="chip" data-act="chipt" aria-pressed="false">Hide done</button><button class="chip" data-act="toast:Saved view “Copy team” shared with the project.:ok">${ic('star',14)}Save view</button></div>
${['todo','prog','review','done'].map(s=>{const r=T.filter(t=>t.st===s);return `<section class="tgroup"><div class="grp-h"><button class="iconbtn sm" aria-label="Collapse">${ic('down',16)}</button>${stPill(s)}<span class="muted mono" style="font-size:12.5px">${r.length}</span></div><div class="tasklist"><div class="trow hd hm"><span></span><span></span><span>Name</span><span>Assignees</span><span>Due</span><span>Priority</span></div>${r.map(taskRow).join('')}</div>${x.arch?'':`<button class="addrow" data-act="addtask:${id}|${s}">${ic('plus',16)}Add task</button>`}</section>`}).join('')}
${sel?`<div class="selbar"><b>${sel} selected</b>${[['mywork','Status'],['flag','Priority'],['user','Assign'],['cal','Due date'],['layers','Section'],['archive','Archive']].map(([i,l])=>`<button data-act="toast:${l} changed for ${sel} tasks.:ok">${ic(i,16)}<span>${l}</span></button>`).join('')}<button data-act="pclear" aria-label="Clear selection">${ic('x',18)}</button></div>`:''}`}
if(view==='board')body=`<div class="kanban">${['todo','prog','review','done'].map(s=>{const r=T.filter(t=>t.st===s);return `<div class="kcol" data-st="${s}"><div class="kcol-h">${stPill(s)}<span class="muted mono" style="font-size:12.5px">${r.length}</span><button class="iconbtn" style="margin-left:auto;width:32px;height:32px" data-act="addtask:${id}|${s}" aria-label="Add task">${ic('plus',16)}</button></div>${r.map(t=>`<button class="kcard" draggable="${!x.arch}" data-id="${t.id}" data-act="task:${t.id}" data-ctx="task:${t.id}"><span style="display:flex;gap:6px">${t.tags.map(g=>`<span class="tag sm">${g}</span>`).join('')}${priL(t.pri)}</span><b>${t.n}</b><span class="foot">${assignees(t)}<span class="${t.o<3&&t.st!=='done'?'od':''}">${ic('cal',13)} ${dl(t.o)}</span>${t.stt?`<span style="margin-left:auto">${ic('check',12)} ${t.sd}/${t.stt}</span>`:''}</span></button>`).join('')}</div>`}).join('')}</div>`;
if(view==='calendar')body=`<div class="toolbar"><b style="font:700 20px/1 var(--font-d)">October 2026</b><span class="grow"></span><button class="iconbtn" aria-label="Previous month">${ic('right',18).replace('<svg','<svg style="transform:scaleX(-1)"')}</button><button class="btn ghost sm">Today</button><button class="iconbtn" aria-label="Next month">${ic('right',18)}</button></div><div class="cal">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="dh">${d}</div>`).join('')}${Array.from({length:42},(_,i)=>{const o=i-21,d=dOf(o);return `<div class="dc ${d.getMonth()!==9?'out':''} ${o===3?'today':''}"><span class="dn">${d.getDate()}</span>${T.filter(t=>t.o===o).map(t=>`<button class="ev" style="--c:${TST[t.st][1]}" data-act="task:${t.id}">${t.n}</button>`).join('')}</div>`}).join('')}</div>`;
if(view==='timeline'){const L=o=>((o+14)/42*100).toFixed(2);body=`<div class="toolbar"><button class="btn ghost sm">Today</button>${vsw([['d','Days'],['w','Weeks'],['m','Months']],'w','noop')}</div><div class="gantt"><div class="gantt-in"><div class="g-head"><span style="padding:10px 14px;font:600 11.5px/1 var(--font);color:var(--muted);letter-spacing:.06em;text-transform:uppercase">Task</span><div class="wk">${[-14,-7,0,7,14,21].map(o=>`<span>${dOf(o).toLocaleDateString('en-GB',{day:'numeric',month:'short'})}</span>`).join('')}</div></div>${T.map(t=>`<div class="g-row"><span class="gn">${av(t.as)}${t.n}</span><div class="g-track"><button class="g-bar" style="left:${L(t.s)}%;width:${(t.len/42*100).toFixed(2)}%;--c:${TST[t.st][1]}" data-act="task:${t.id}">${t.n}</button></div></div>`).join('')}<div class="g-today" style="left:calc(240px + (100% - 240px) * ${(17/42).toFixed(3)})"></div></div></div><p class="hint" style="margin-top:8px">Waiting-on links draw as arrows between bars. Drag a bar to reschedule.</p>`}
if(view==='workload')body=`<div class="tblwrap"><table class="tbl wl"><thead><tr><th>Member</th><th>This week</th><th>Next week</th><th>Open tasks</th></tr></thead><tbody>${x.team.map((k,i)=>`<tr><td class="t1"><span style="display:flex;gap:8px;align-items:center">${av(k)}${PEOPLE[k][0]}</span></td>${[[18,26],[34,12],[28,30],[10,8],[6,4]][i%5].map(h=>`<td><span class="wcell ${h>32?'high':''}" style="--v:${h/40*100}%"><b>${h}h</b></span></td>`).join('')}<td>${T.filter(t=>t.as===k&&t.st!=='done').length}</td></tr>`).join('')}</tbody></table></div>`;
if(view==='report'){const n={};T.forEach(t=>n[t.st]=(n[t.st]||0)+1);body=`<div class="kpis">${[[T.filter(t=>t.st!=='done').length,'Open'],[T.filter(t=>t.o<3&&t.st!=='done').length,'Overdue'],[1,'Blocked'],[T.filter(t=>t.st==='done').length,'Done in 30 days'],['31h','Estimated left']].map(([b,s])=>`<div><b>${b}</b><span>${s}</span></div>`).join('')}</div><div class="grid2" style="margin-top:18px"><section class="panel" style="padding:18px 20px"><p class="sec-t" style="margin-top:0">Tasks by status</p>${Object.keys(TST).map(s=>`<div class="ws-bar"><span class="nm">${TST[s][0]}</span><span class="prog" style="--v:${(n[s]||0)/T.length*100}%"><i style="background:${TST[s][1]}"></i></span><span class="mono" style="width:30px;text-align:right">${n[s]||0}</span></div>`).join('')}</section><section class="panel" style="padding:18px 20px"><p class="sec-t" style="margin-top:0">Completed per week</p><div class="spark">${[2,4,3,6,5,7].map(v=>`<i style="--v:${v*12}px"></i>`).join('')}</div></section></div><div class="tblwrap" style="margin-top:18px"><table class="tbl"><thead><tr><th>Person</th><th>Open</th><th>Overdue</th><th>Done</th><th>Estimated left</th><th>Billable</th></tr></thead><tbody>${x.team.map(k=>`<tr><td class="t1"><span style="display:flex;gap:8px;align-items:center">${av(k)}${PEOPLE[k][0]}</span></td><td data-l="Open">${T.filter(t=>t.as===k&&t.st!=='done').length}</td><td data-l="Overdue">0</td><td data-l="Done">${T.filter(t=>t.as===k&&t.st==='done').length}</td><td data-l="Estimated left">6h</td><td data-l="Billable">4h 20m</td></tr>`).join('')}</tbody></table></div>`}
if(view==='files')body=`<div class="toolbar"><span class="grow tx2">Owned by this project. Not copied to Drive.</span><button class="btn primary" data-act="newres">${ic('plus',18,'',2.2)}New</button></div><div class="cardgrid">${[['doc','Project brief','DOC','drive/edit/doc/brief'],['sheet','Quiz scoring sheet','XLS','drive/edit/sheet/cal'],['image','Quiz flow v1','IMG','drive/edit/image/hero'],['pdf','Signed proposal','PDF','drive/edit/pdf/prop']].map(([t,n,l,h],i)=>`<a class="card" href="#/${h}"><div class="thumb" data-t="${t}" style="border-radius:12px"></div><h3>${n}</h3><div class="foot"><span class="ft ${t}">${l}</span>Updated ${dl(3-i)}</div></a>`).join('')}<a class="card" href="#/whiteboard/board/b1"><div class="thumb" style="border-radius:12px;background:radial-gradient(var(--line2) 1px,transparent 1px) 0 0/12px 12px,var(--surface2)"></div><h3>Quiz flow board</h3><div class="foot">Whiteboard</div></a></div>`;
if(view==='rules')body=`<div class="toolbar"><span class="grow tx2">Rules run on their own so the board stays tidy.</span><button class="btn primary" data-act="toast:Add a rule: When … Then …">${ic('plus',18,'',2.2)}Add rule</button></div><div style="display:grid;gap:10px;max-width:760px">${[['a task moves to Blocked','set priority to Urgent',1],['a task is added to “Copy”','assign it to Sana Noor',1],['a task moves to Review','make it due in 2 days',0]].map(([w,t,on])=>`<div class="rule"><span class="wic" style="--c:#2B5CF0;width:40px;height:40px">${ic('sparkle',18)}</span><p><b>When</b> ${w}, <b>then</b> ${t}.</p><button class="toggle" role="switch" aria-checked="${!!on}" data-act="tgl" aria-label="Rule on"></button><button class="iconbtn" aria-label="Remove rule" data-act="toast:Rule removed.">${ic('trash',16)}</button></div>`).join('')}</div>`;
const banner=x.arch?`<div class="notice plain" style="margin-bottom:16px">${ic('archive',20)}<span><b>Archived.</b> Read only. Hidden everywhere except search.</span><button class="btn ink sm" style="margin-left:auto" data-act="parch:${id}">Restore</button></div>`:'';
return pShell('',`${banner}<div class="ph"><span class="pbig" style="--c:${x.c}">${ic('projects',22,'',2)}</span><div><h1>${x.n}</h1><div class="meta"><span>${x.cl}</span>·<span style="display:inline-flex;gap:6px;align-items:center">${av(x.lead)}${PEOPLE[x.lead][0]}</span>·<span>Due ${x.due}</span><span class="pill ${PSTAT[x.st]}">${x.st}</span></div></div><div class="acts">${avs(x.team.slice(0,4))}<button class="btn ghost sm" data-act="members:${id}">${ic('users',16)}<span class="hide-m">Members</span></button><button class="iconbtn" aria-label="Project actions" data-act="pmenu:${id}">${ic('more')}</button></div></div>
<div class="tabs ptabs" role="tablist">${V.map(([k,l,n])=>`<a role="tab" href="#/projects/p/${id}/${k}" aria-selected="${k===view}">${l}${n!=null?`<span class="n">${n}</span>`:''}</a>`).join('')}<button class="tabadd" data-act="viewgal" aria-label="Add a view">${ic('plus',16)}View</button></div>${body}`,[['Projects','projects/home'],[x.cl==='Internal'?oname():x.cl],[x.n]])}
function taskDrawer(id){const[pid,i]=id.split('-');const t=tasksOf(pid)[+i],x=proj(pid);
openDrawer(`<div class="drw-h"><span class="pdot" style="--c:${x.c}"></span><small class="muted grow">${x.n} › ${t.tags[0]||'No section'}</small><button class="btn quiet sm" data-act="toast:You’ll get updates on this task.:ok">${ic('bell',16)}Follow</button><button class="iconbtn" data-act="toast:Link copied.:ok" aria-label="Copy link">${ic('link')}</button><button class="iconbtn" data-act="drawerx" aria-label="Close">${ic('x')}</button></div>
<input class="drw-title" value="${esc(t.n)}" aria-label="Task name">
<dl class="props"><dt>${ic('mywork',16)}Status</dt><dd><select class="sel" data-tst="${id}" aria-label="Status">${Object.entries(TST).map(([k,v])=>`<option value="${k}" ${k===t.st?'selected':''}>${v[0]}</option>`).join('')}</select></dd><dt>${ic('users',16)}Assignees</dt><dd>${[t.as,...(t.co||[])].map(k=>`<span class="chip sm">${av(k)}${PEOPLE[k][0].split(' ')[0]}</span>`).join('')}<button class="linkbtn" style="font-size:13px" data-act="noop">+ Add</button></dd><dt>${ic('cal',16)}Dates</dt><dd>${dl(t.s)} → ${dl(t.o)}</dd><dt>${ic('flag',16)}Priority</dt><dd>${priL(t.pri)}</dd><dt>${ic('timer',16)}Estimate</dt><dd>4h</dd><dt>${ic('refresh',16)}Repeat</dt><dd class="muted">Doesn’t repeat</dd><dt>${ic('tag',16)}Tags</dt><dd>${t.tags.map(g=>`<span class="tag">${g}</span>`).join('')}</dd>
<dt>${ic('sliders',16)}Funnel stage</dt><dd><span class="pill">Copy</span><span class="pill" style="height:20px;font-size:10.5px">Custom field</span></dd><dt>${ic('portal',16)}Client sees</dt><dd><button class="toggle" role="switch" aria-checked="false" data-act="tgl" aria-label="Client can see this task"></button></dd></dl>
<div class="sec-t">${ic('timer',16)}Time</div><div class="timer" id="tmr"><button class="btn ink sm" data-act="timer">${ic('play',16)}Start</button><b>00:00:00</b><small class="muted">Logged 2h 10m · billable</small></div>
<div class="sec-t">Description</div><p class="tx2" contenteditable="true" style="padding:10px;border-radius:10px;border:1px solid var(--line)">Write ten quiz questions that sort visitors into three goals. Use Harry’s language from the interview.</p>
<div class="sec-t">${ic('check',16)}Subtasks <span class="muted mono">${t.sd}/${t.stt}</span></div><div class="checkl">${Array.from({length:t.stt||2},(_,j)=>`<div class="row ${j<t.sd?'done':''}"><button class="cbx" role="checkbox" aria-checked="${j<t.sd}" data-act="sub" aria-label="Toggle subtask"><i>${ic('check',14,'',3)}</i></button><div class="main"><b>${['Draft questions','Check against avatar','Send to Harry','Revise from notes','Final read','Hand to build'][j%6]}</b></div></div>`).join('')}</div>
<div class="sec-t">${ic('link',16)}Waiting on</div><div class="linkrow" style="background:var(--sunk);min-height:44px">${ic('alert',16)}<span class="main"><b>Customer avatar draft</b><small>Review · Usman</small></span></div>
<div class="sec-t">${ic('clip',16)}Files</div><div style="display:flex;gap:8px;flex-wrap:wrap"><span class="chip">${ic('doc',16)}Quiz brief</span><button class="chip" data-act="toast:Pick from Drive or upload.">${ic('upload',16)}Add file</button></div>
<div class="sec-t">${ic('msg',16)}Comments <span class="grow"></span>${vsw([['c','Comments'],['a','All activity']],'c','noop')}</div><div class="comment">${av('UM')}<div class="bub">@Sana Harry prefers “get fit” over “lose weight”.<br><small>1 h ago</small></div></div><div class="comment">${av('SN')}<div class="bub">Updating question 3 now.<br><small>40 min ago</small></div></div><div class="compose"><textarea placeholder="Comment. Type @ to mention." aria-label="Comment"></textarea><button class="btn ink" data-act="toast:Comment posted.:ok" aria-label="Send">${ic('send',18)}</button></div>`,'wide')}
let TMR=null;
CTX.task=v=>[['edit','Open','task:'+v,'','Enter'],['copy','Duplicate','toast:Task duplicated.:ok','','Ctrl D'],['link','Copy link','toast:Link copied.:ok'],['arrow','Open in new tab','toast:Opens in a new tab.'],'-',['user','Assign…','noop'],['flag','Priority…','noop'],['cal','Due date…','noop'],['layers','Move to section…','noop'],'-',['archive','Archive','toast:Task archived.','danger']];
CTX.proj=v=>[['arrow','Open','nav:projects/p/'+v+'/list'],['star','Favourite','toast:Added to favourites.:ok'],['copy','Duplicate','toast:Duplicated.:ok'],['copy','Save as template','toast:Saved as template.:ok'],'-',['archive','Archive project','parch:'+v,'danger']];
Object.assign(ACT,{task:v=>taskDrawer(v),
tdone:v=>{const[p,i]=v.split('-');const t=TASKS[p][+i];t.st=t.st==='done'?'todo':'done';if(t.st==='done')toast('Task done.','ok',1500);draw()},
psel:v=>{PV.sel.has(v)?PV.sel.delete(v):PV.sel.add(v);draw()},pclear:()=>{PV.sel.clear();draw()},
quickadd:()=>dlg({title:'Quick add',body:`<div class="field" style="margin-top:12px"><label for="qa">Task</label><input id="qa" placeholder="e.g. Send quiz v2 to Harry tomorrow @Sana #copy !high"></div><p class="hint">Understands dates (tomorrow, Fri), @people, #tags and !priority.</p><div class="field"><label for="qp">Project</label><select id="qp">${projs().filter(x=>!x.arch).map(x=>`<option>${x.n}</option>`).join('')}</select></div>`,acts:[['Cancel','noop'],['Add task','toast:Task added.:ok','primary']]}),
addtask:v=>{const[p,s]=v.split('|');dlg({title:'Add task',body:`<div class="field" style="margin-top:12px"><label for="nt">Task name</label><input id="nt" placeholder="What needs doing?"></div><div class="row2"><div class="field"><label for="nta">Assignee</label><select id="nta">${Object.keys(PEOPLE).map(k=>`<option value="${k}">${PEOPLE[k][0]}</option>`).join('')}</select></div><div class="field"><label for="ntp">Priority</label><select id="ntp">${Object.keys(PRI).map(k=>`<option value="${k}" ${k==='normal'?'selected':''}>${PRI[k][0]}</option>`).join('')}</select></div></div>`,acts:[['Cancel','noop'],['Add task',`addtask2:${p}|${s}`,'primary']]});setTimeout(()=>$('#nt')?.focus(),40)},
addtask2:v=>{const[p,s]=v.split('|');TASKS[p].push(mk(($('#nt')?.value||'').trim()||'New task',s,$('#nta').value,7,$('#ntp').value,['New'],0,0,4,4));draw();toast('Task added.','ok')},
members:v=>dlg({title:'Project members',body:`<label class="inp" style="margin:12px 0">${ic('user',18)}<input placeholder="Add people by name or email"></label>${proj(v).team.map(k=>`<div class="linkrow" style="min-height:48px">${av(k)}<span class="main"><b>${PEOPLE[k][0]}</b></span><select class="sel"><option>Member</option><option ${k===proj(v).lead?'selected':''}>Lead</option><option>Remove</option></select></div>`).join('')}<p class="hint">Members see this project even if their app level is lower. Non-members can’t find it.</p>`,acts:[['Done','noop','primary']]}),
pmenu:v=>{const x=proj(v);dlg({title:x.n,body:`<div style="display:grid;gap:4px;margin-top:8px">${[['edit','Edit details','toast:Edit name, client, dates and lead.'],['copy','Duplicate','toast:Duplicated.:ok'],['copy','Save as template','toast:Saved as template.:ok'],[x.arch?'restore':'archive',x.arch?'Restore project':'Archive project','parch:'+v]].map(([i,l,a])=>`<button class="linkrow" data-act="${a}">${ic(i)}<span class="main"><b>${l}</b></span></button>`).join('')}</div>`,acts:[['Close','noop']]})},
parch:v=>{const x=proj(v);x.arch=!x.arch;toast(x.arch?`“${x.n}” archived. Find it with search: is:archived`:`“${x.n}” restored.`,'ok');nav(x.arch?'projects/home':`projects/p/${v}/overview`)},
newproj:()=>dlg({title:'New project',body:`<div class="field" style="margin-top:12px"><label for="np">Project name</label><input id="np"></div><div class="row2"><div class="field"><label for="npc">Belongs to</label><select id="npc"><option>Internal</option><option>Harry Kaye PT</option><option>Mindful Money Co</option><option>Personal (only you)</option></select></div><div class="field"><label for="npt">Start from</label><select id="npt"><option>Blank</option><option>Client funnel build</option><option>Course launch</option></select></div></div>`,acts:[['Cancel','noop'],['Create project','newproj2','primary']]}),
newproj2:()=>{const n=($('#np')?.value||'').trim()||'Untitled project';const id='n'+Date.now();projs().push({id,n,cl:$('#npc').value,lead:'TR',st:'Planning',pr:0,due:'Dec',c:'#2B63F6',team:['TR'],purpose:'Add a purpose so everyone knows why this exists.'});TASKS[id]=[];nav(`projects/p/${id}/overview`)},
viewgal:()=>dlg({title:'Add a view',body:`<div class="grid3" style="gap:8px;margin-top:10px">${[['list','List'],['board','Board'],['cal','Calendar'],['gantt','Timeline'],['table','Table'],['users','Workload'],['chart','Report'],['mindmap','Mind map'],['doc','Doc']].map(([i,l])=>`<button class="linkrow" style="flex-direction:column;border:var(--bw) solid var(--line)" data-act="toast:“${l}” view added and shared with members.:ok">${ic(i,22)}<b>${l}</b></button>`).join('')}</div>`,acts:[['Close','noop']]}),
newres:()=>dlg({title:'New in this project',body:`<div class="grid3" style="gap:8px;margin-top:10px">${[['doc','Document'],['sheetI','Spreadsheet'],['whiteboard','Whiteboard'],['upload','Upload'],['link','Link'],['mic','Audio note']].map(([i,l])=>`<button class="linkrow" style="flex-direction:column;border:var(--bw) solid var(--line)" data-act="toast:${l} created in this project.:ok">${ic(i,22)}<b>${l}</b></button>`).join('')}</div>`,acts:[['Close','noop']]}),
timer:(v,t)=>{const w=$('#tmr');if(TMR){clearInterval(TMR);TMR=null;w.classList.remove('run');t.innerHTML=ic('play',16)+'Resume';toast('Time saved to this task.','ok');return}let s=+(w.dataset.s||0);w.classList.add('run');t.innerHTML=ic('pause',16)+'Pause';TMR=setInterval(()=>{if(!document.body.contains(w)){clearInterval(TMR);TMR=null;return}s++;w.dataset.s=s;$('b',w).textContent=new Date(s*1000).toISOString().slice(11,19)},1000)}});
KEY.projects=(e,typing)=>{if(!typing&&e.key.toLowerCase()==='q'&&!e.ctrlKey&&!e.metaKey){e.preventDefault();ACT.quickadd()}};
document.addEventListener('change',e=>{const s=e.target.dataset.tst;if(s){const[p,i]=s.split('-');TASKS[p][+i].st=e.target.value;toast('Status updated.','ok',1500)}if(e.target.hasAttribute('data-pg')){PV.group=e.target.value;toast('Grouped by '+e.target.value+'.')}});
let dragId=null;
document.addEventListener('dragstart',e=>{const c=e.target.closest?.('.kcard');if(c){dragId=c.dataset.id;c.classList.add('dragging')}});
document.addEventListener('dragend',e=>{e.target.closest?.('.kcard')?.classList.remove('dragging');$$('.kcol.over').forEach(c=>c.classList.remove('over'))});
document.addEventListener('dragover',e=>{const c=e.target.closest?.('.kcol');if(c&&dragId){e.preventDefault();c.classList.add('over')}});
document.addEventListener('drop',e=>{const c=e.target.closest?.('.kcol');if(c&&dragId&&c.dataset.st){e.preventDefault();const[p,i]=dragId.split('-');TASKS[p][+i].st=c.dataset.st;dragId=null;draw();toast('Moved.','ok',1200)}});
SEARCH.push(()=>[...projs().map(p=>({app:'projects',t:p.n,s:p.cl+' · '+p.st,href:`projects/p/${p.id}/overview`,arch:!!p.arch})),...allTasks().map(t=>({app:'projects',t:t.n,s:proj(t.pid).n+' · '+PEOPLE[t.as][0]+' · '+dl(t.o),href:`projects/p/${t.pid}/list`,me:t.as==='TR',od:t.o<3&&t.st!=='done',arch:!!proj(t.pid).arch}))]);
